public class Solution {
    public int solve(int A, int B, int C) {
        int n = A, r = B, m = C;
        long[][] dp = new long[n + 1][r + 1];
        for (int i = 0; i <= n; i++) {
            dp[i][0] = 1 % m;
            for (int j = 1; j <= Math.min(i, r); j++) {
                dp[i][j] = (dp[i - 1][j - 1] + dp[i - 1][j]) % m;
            }
        }
        return (int) dp[n][r];
    }
}

public class Solution {
    public int solve(int A) {
        long count = 0;
        for (long i = 1; i <= A; i *= 10) {
            long high = A / (i * 10);
            long cur = (A / i) % 10;
            long low = A % i;
            if (cur == 0) {
                count += high * i;
            } else if (cur == 1) {
                count += high * i + low + 1;
            } else {
                count += (high + 1) * i;
            }
        }
        return (int) count;
    }
}

public class Solution {
    public int solve(int A) {
        int count = 0;
        long k = 1;
        while (k * (k - 1) / 2 < A) {
            long rem = A - k * (k - 1) / 2;
            if (rem % k == 0) {
                count++;
            }
            k++;
        }
        return count;
    }
}

