public class Solution {
    public int[][] solve(int A) {
        int[][] res = new int[A][A];
        for (int i = 0; i < A; i++) {
            res[i][0] = 1;
            for (int j = 1; j <= i; j++) {
                res[i][j] = res[i - 1][j] + res[i - 1][j - 1];
            }
        }
        return res;
    }
}

